&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_o_problema_três_arquiteturas_que_me_fizeram_perder_tempo&quot;&gt;O Problema : Três Arquiteturas Que Me Fizeram Perder Tempo&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_opção_1_o_plugin_isolado_sem_dogfooding&quot;&gt;Opção 1 : O Plugin Isolado (sem dogfooding)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_opção_2_o_monorepo_clássico_includeplugin&quot;&gt;Opção 2: O Monorepo Clássico (&lt;code&gt;include(&quot;:plugin&quot;)&lt;/code&gt;)&lt;/a&gt;&lt;/li&gt;
