&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_introdução&quot;&gt;Introdução&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_por_que_gradle_para_da_infra&quot;&gt;Por que Gradle para da Infra ?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_o_build_gradle_kts_completo&quot;&gt;O build.gradle.kts completo&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_anatomia_das_tarefas_chave&quot;&gt;Anatomia das Tarefas Chave&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_startollamab_o_lançador&quot;&gt;startOllamaB` — O Lançador&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_signinb_o_interativo&quot;&gt;signInB` — O Interativo&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_pullmodelb_o_configurável&quot;&gt;pullModelB` — O configurável&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_statusollamaall_o_diagnóstico&quot;&gt;statusOllamaAll` — O Diagnóstico&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_cleanollamab_a_limpeza_que_preserva_a_identidade&quot;&gt;cleanOllamaB` — A limpeza que preserva a identidade&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_workflow_completo_de_zero_a_duas_sessões&quot;&gt;Workflow Completo — De Zero a Duas Sessões&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_por_que_não_transformá_lo_em_um_plugin_gradle_real&quot;&gt;Por que não transformá-lo em um plugin Gradle real?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_lições_aprendidas&quot;&gt;Lições Aprendidas&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_conclusão&quot;&gt;Conclusão&lt;/a&gt;&lt;/li&gt;
