&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://ollama.com/settings/keys&quot;&gt;Ollama Settings — Gerenciamento de chaves SSH&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.ollama.com/&quot;&gt;Documentação oficial Ollama&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://hub.docker.com/r/ollama/ollama&quot;&gt;Imagem Docker Ollama no Docker Hub&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://opencode.ai/docs/providers/#ollama&quot;&gt;OpenCode — Provedor de Configuração Ollama&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
