left to right direction

rectangle &quot;Cache KV
1M tokens&quot; as KV #E3F2FD

rectangle &quot;CSA
Atenção Esparsa Comprimida&quot; as CSA #C8E6C9 {
  rectangle &quot;Compressão
m tokens → 1&quot; as CC
  rectangle &quot;Atenção Esparsa
(DSA, top-k)&quot; as SA
  CC --&amp;gt; SA

  note bottom of SA
    Attention locale fine
    + sélection sparse
  end note
}

