BOM1 --&amp;gt; RES : &quot;propõe 1.20.6&quot;
WIN -&amp;gt; MC : &quot;baixe\ntestcontainers:1.20.6&quot;

note bottom of WIN
  Spring Boot BOM prime car
  le plugin spring-boot applique
  ses dépendances de gestion
  après la résolution du consommateur
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_fase_4_forçar_a_resolução&quot;&gt;Fase 4 : forçar a resolução&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;A estratégia se torna dupla:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Forçar o docker-java para sua versão 3.7.1 (testada como compatível com Docker Engine 29)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Force o Testcontainers core para 2.0.5 contornando o BOM do Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div id=&quot;diag-resolution-override&quot; class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 9) ]

@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false
skinparam componentStyle rectangle

left to right direction

component &quot;build.gradle\n(com resolutionStrategy)&quot; as BG #E8F5E9 {
    rectangle &quot;BOM Testcontainers
^^^^^
 Syntax Error? (Assumed diagram type: class)

@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false
skinparam componentStyle rectangle

left to right direction

component &quot;build.gradle\n(com resolutionStrategy)&quot; as BG #E8F5E9 {
    rectangle &quot;BOM Testcontainers
`2.0.5&quot; as BOM2
    rectangle &quot;resolutionStrategy\n.eachDependency&quot; as RS #66BB6A
}

component &quot;Conflito resolvido&quot; as RESOLVED #E3F2FD {
    rectangle &quot;docker-java\n`3.7.1` (forçado)&quot; as DJ
    rectangle &quot;testcontainers
`2.0.5` (forçado)&quot; as TC #81C784
    rectangle &quot;testcontainers-postgresql
`2.0.5&quot; as TPG
    rectangle &quot;testcontainers-jdbc
`2.0.5&quot; as TJ
    rectangle &quot;testcontainers-junit-jupiter
`2.0.5&quot; as TJJ
}

component &quot;BOM Spring Boot\n(implícito, sobrescrito)&quot; as BOM1 #FFEBEE

component &quot;Maven Central&quot; as MC #FFF3E0

BG --&amp;gt; RESOLVED : &quot;BOM Testcontainers 2.0.5\npassa diretamente&quot;
RS -&amp;gt; DJ : &quot;força 3.7.1&quot;
RS -&amp;gt; TC : &quot;força 2.0.5&quot;
RESOLVED --&amp;gt; MC : &quot;Baixe os JARs\ncompatíveis com Docker 29&quot;
BOM1 -[#gray,dashed]-&amp;gt; RESOLVED : &quot;ignorado no testcontainers\net docker-java&quot;

note bottom of RS
  Le `eachDependency` intercepte
  la résolution Gradle AVANT
  que le BOM Spring Boot ne gagne.
  C&#39;est une intervention chirurgicale.
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Correção final&lt;/strong&gt;em`build.gradle`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-groovy hljs&quot; data-lang=&quot;groovy&quot;&gt;configurations {
    all {
        resolutionStrategy.eachDependency { details -&amp;gt;
            if (details.requested.group == &quot;com.github.docker-java&quot;
                &amp;amp;&amp;amp; details.requested.name.startsWith(&quot;docker-java&quot;)) {
                details.useVersion(&quot;3.7.1&quot;)
            }
            if (details.requested.group == &quot;org.testcontainers&quot;
                &amp;amp;&amp;amp; details.requested.name == &quot;testcontainers&quot;) {
                details.useVersion(&quot;2.0.5&quot;)
            }
        }
    }
}

dependencies {
    testImplementation platform(&quot;org.testcontainers:testcontainers-bom:2.0.5&quot;)
    testImplementation &quot;org.testcontainers:testcontainers-jdbc&quot;
    testImplementation &quot;org.testcontainers:testcontainers-junit-jupiter&quot;
    testImplementation &quot;org.testcontainers:testcontainers-postgresql&quot;
    testImplementation &quot;org.testcontainers:testcontainers&quot;
    // ... autres dépendances Spring Boot
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Le `resolutionStrategy.eachDependency`é a única maneira de contornar o BOM`spring-boot-dependencies`gerenciado pelo plugin Spring Boot. O teste de igualdade sobre`details.requested.name == &quot;testcontainers&quot;`é voluntariamente restritivo: forçamos apenas o módulo core. Os módulos`testcontainers-*`Seguem o BOM do Testcontainers 2.0.5 que declaramos explicitamente&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_resultado_final&quot;&gt;Resultado final&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ./gradlew build --no-daemon

&amp;gt; Task :consoleLauncherTest
[2 containers found]
[2 containers started]
[2 containers successful]

BUILD SUCCESSFUL in 1m 16s&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Testcontainers 2.0.5 + docker-java 3.7.1 finalmente conseguem criar seus containers PostgreSQL via Docker Engine 29.4.1. O erro de negócio final (HTTP 500 no teste Cucumber) é um problema de aplicação totalmente independente do script de build.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
