skinparam backgroundColor #FEFEFE

rectangle &quot;Paradigma Antigo&quot; #LightCoral {
  card &quot;Tudo no Backend&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

