&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_antes_abordagem_problemática&quot;&gt;Antes : Abordagem Problemática&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_depois_abordagem_robusta&quot;&gt;Depois: Abordagem Robusta&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_diagrama_resumo&quot;&gt;Diagrama Resumo&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_armadilhas_a_evitar&quot;&gt;armadilhas a evitar&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_armadilha_nº1_esquecer_forwardoutput&quot;&gt;Armadilha nº1 : Esquecer `.forwardOutput()&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_armadilha_n2_logger_não_inicializado&quot;&gt;❌ Armadilha n°2: Logger Não Inicializado&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_armadilha_nº_3_log_excessivo&quot;&gt;Armadilha nº 3 : Log excessivo&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_resultados_e_métricas&quot;&gt;Resultados e Métricas&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_conclusão&quot;&gt;Conclusão&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_recursos&quot;&gt;Recursos&lt;/a&gt;&lt;/li&gt;
