&lt;li&gt;&lt;a href=&quot;#_problema_1_verificar_o_mock_errado&quot;&gt;Problema #1: Verificar o mock errado&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_o_diagnóstico&quot;&gt;O diagnóstico&lt;/a&gt;&lt;/li&gt;
