&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_problema_2_unfinishedstubbingexception_em_cascata&quot;&gt;Problema #2 : UnfinishedStubbingException em cascata&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_o_diagnóstico_2&quot;&gt;O diagnóstico&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_a_solução_2&quot;&gt;A solução&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_problema_3_o_arquivo_de_configuração_não_existe&quot;&gt;Problema #3: O arquivo de configuração não existe&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_o_diagnóstico_3&quot;&gt;O diagnóstico&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_a_solução_3&quot;&gt;A solução&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_problema_4_afterevaluate_e_nullpointerexception&quot;&gt;Problema #4 : afterEvaluate e NullPointerException&lt;/a&gt;
