&lt;li&gt;&lt;a href=&quot;#_o_diagnóstico_4&quot;&gt;O diagnóstico&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_a_solução_4&quot;&gt;A solução&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
